CREATE TABLE IF NOT EXISTS association_profiles (id TEXT PRIMARY KEY, municipality TEXT NOT NULL, association_slug TEXT NOT NULL, data_json TEXT NOT NULL, updated_by TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(municipality, association_slug));
CREATE TABLE IF NOT EXISTS association_posts (id TEXT PRIMARY KEY, municipality TEXT NOT NULL, association_slug TEXT NOT NULL, title TEXT NOT NULL, event_at TEXT, place TEXT NOT NULL DEFAULT '', body TEXT NOT NULL DEFAULT '', link TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1, created_by TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS association_posts_profile ON association_posts(municipality, association_slug, active, event_at);
CREATE TABLE IF NOT EXISTS association_media (id TEXT PRIMARY KEY, municipality TEXT NOT NULL, association_slug TEXT NOT NULL, media_type TEXT NOT NULL, object_key TEXT NOT NULL UNIQUE, file_name TEXT NOT NULL, content_type TEXT NOT NULL, file_size INTEGER NOT NULL, moderation_status TEXT NOT NULL DEFAULT 'pending', review_comment TEXT NOT NULL DEFAULT '', uploaded_by TEXT NOT NULL, reviewed_by TEXT, reviewed_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS association_media_review ON association_media(moderation_status, created_at);
CREATE TABLE IF NOT EXISTS association_audit_log (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, municipality TEXT NOT NULL, association_slug TEXT NOT NULL, operation TEXT NOT NULL, field_name TEXT NOT NULL, old_value TEXT NOT NULL DEFAULT '', new_value TEXT NOT NULL DEFAULT '', moderation_status TEXT NOT NULL DEFAULT 'published', created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS association_audit_profile ON association_audit_log(municipality, association_slug, created_at);
CREATE TABLE IF NOT EXISTS association_ledger (id TEXT PRIMARY KEY, municipality TEXT NOT NULL, association_slug TEXT NOT NULL, entry_type TEXT NOT NULL, amount_ore INTEGER NOT NULL, source_type TEXT NOT NULL, source_id TEXT NOT NULL DEFAULT '', reference TEXT NOT NULL DEFAULT '', occurred_at TEXT NOT NULL, created_by TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS association_ledger_profile ON association_ledger(municipality, association_slug, occurred_at);
CREATE UNIQUE INDEX IF NOT EXISTS association_ledger_source ON association_ledger(entry_type, source_type, source_id) WHERE source_id <> '';
